import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

function invalid(message) {
  throw new Error(message);
}

function validateRules(rules) {
  if (!Array.isArray(rules)) invalid('rules must be an array');

  const ids = new Set();
  const validated = [];
  for (let index = 0; index < rules.length; index += 1) {
    if (!(index in rules)) invalid('rules must be a dense array');

    const rule = rules[index];
    if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
      invalid('each rule must be an object');
    }

    const {id, literal, replacement} = rule;
    if (typeof id !== 'string' || id.length === 0) invalid('rule id must be a nonempty string');
    if (ids.has(id)) invalid('rule ids must be unique');
    if (typeof literal !== 'string' || literal.length === 0) {
      invalid('rule literal must be a nonempty string');
    }
    if (typeof replacement !== 'string') invalid('rule replacement must be a string');

    ids.add(id);
    // Snapshot the relevant fields so later work never needs to modify inputs.
    validated.push({id, literal, replacement, index});
  }
  return validated;
}

export function planRedactions(text, rules) {
  if (typeof text !== 'string') invalid('text must be a string');
  const validated = validateRules(rules);
  const matches = [];

  for (const rule of validated) {
    let start = text.indexOf(rule.literal);
    while (start !== -1) {
      matches.push({start, end: start + rule.literal.length, rule});
      // Advancing by one finds overlaps as well as nonoverlapping occurrences.
      start = text.indexOf(rule.literal, start + 1);
    }
  }

  matches.sort((left, right) =>
    left.start - right.start ||
    right.rule.literal.length - left.rule.literal.length ||
    left.rule.index - right.rule.index);

  const selected = [];
  let nextAvailable = 0;
  for (const match of matches) {
    if (match.start >= nextAvailable) {
      selected.push(match);
      nextAvailable = match.end;
    }
  }

  let output = '';
  let cursor = 0;
  const edits = [];
  for (const match of selected) {
    output += text.slice(cursor, match.start) + match.rule.replacement;
    cursor = match.end;
    edits.push({start: match.start, end: match.end, id: match.rule.id});
  }
  output += text.slice(cursor);

  return {
    text: output,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(output, 'utf8'),
  };
}

function runCli() {
  if (process.argv.length !== 3) invalid('usage: node redaction-plan.js INPUT_JSON_FILE');
  const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    invalid('input JSON must be an object');
  }
  process.stdout.write(`${JSON.stringify(planRedactions(input.text, input.rules))}\n`);
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    runCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : 'invalid input'}\n`);
    process.exitCode = 2;
  }
}

